INSERT INTO `plan` (`id`, `locationid`, `title`, `description`, `details`, `plantype`, `amount`, `peopleallowed`, `maxpeopleallowed`, `givediscount`, `maxdiscount`, `effectivedate`, `enddate`, `galleryimages`) VALUES
(1, 1, 'Red Love', '•	Experience ultimate romantic ambiance\n•	6ft heart-shaped décor\n•	Adorned with vibrant red balloons\n•	Customizable neon lights backdrop\n•	Private space for special occasions\n•	Caters to birthdays, anniversaries, and more\n•	Luxurious sofa seating\n•	Premium amenities: cake stand, customized LED name board\n•	Perfect for couples and small groups\n•	Unforgettable, exclusive celebration\n', NULL, 1, 1299, 2, 8, 1, 300, '2026-03-31', '2026-08-31', '[\"gallery/Hulimavu/1/1.jpg\", \"gallery/Hulimavu/1/2.jpg\", \"gallery/Hulimavu/1/1.gif\"]'),
(2, 1, 'Peachy Glam', '•	Adorned with soft pink and rose gold balloons for an elegant touch.\n•	Enchanting 4-feet circle shaped decor\n•	Cozy private seating for up to 6 guests, perfect for intimate celebrations.\n•	Immersive ambiance with fog effects, creating a dreamy atmosphere.\n•	Premium amenities: cake stand, customized LED name board\n•	Space offers projection and HD screen\n•	Pre-installed OTT apps for entertainment\n•	Wall lighting for a memorable event\n', NULL, 1, 799, 2, 8, 1, 300, '2025-08-27', '2026-03-30', '[\"gallery/Hulimavu/2/1.jpg\", \"gallery/Hulimavu/2/2.jpg\"]'),
(3, 1, 'Lavender Retreat', '•	A dreamy setup with soft lavender and deep purple balloons for a magical touch.\n•	Stunning butterfly-themed cake stand and decor for a fairytale vibe.\n•	Private space accommodates up to 8 guests\n•	Backdrop neon lights adapt to your occasion\'s theme\n•	Sophisticated ambiance\n•	Premium amenities: cake stand, customized LED name board\n•	Projection screen & pre-installed OTT apps for an immersive entertainment experience.\n•	Immersive ambiance with fog effects, creating a dreamy atmosphere.\n', NULL, 1, 1600, 4, 10, 1, 300, '2026-04-12', '2026-08-31', '[\"gallery/Hulimavu/3/2.jpg\", \"gallery/Hulimavu/3/1.jpg\"]'),
(4, 1, 'Cinematic Royalty', '•	Luxurious blue and gold balloon décor for a grand and elegant vibe.\r\n•	A magical fog effect with glowing lights creates a dreamy atmosphere.\r\n•	Backdrop neon lights adapt to your occasion\'s theme\r\n•	Cozy private lounge seating for up to 30 guests, ensuring a comfortable celebration.\r\n•	Premium amenities: cake stand, customized LED name board\r\n•	Cinematic experience with a projection screen and pre-installed OTT apps.\r\n•	Premium gold-themed decor, including lanterns and a carousel centerpiece for a regal touch.\r\n•	Perfect for birthdays, milestone celebrations, and exclusive gatherings!\r\n', NULL, 1, 1600, 4, 30, 1, 300, '2026-04-12', '2026-08-31', '[\"gallery/Hulimavu/4/1.jpg\", \"gallery/Hulimavu/4/2.jpg\"]'),
(5, 2, 'Saphire suite', '•	Adorned with soft Blue and Silver balloons for an elegant touch.\r\n•	Enchanting 4-feet rectangular shaped decor\r\n•	Cozy private seating for up to 6 guests, perfect for intimate celebrations.\r\n•	Immersive ambiance with fog effects, creating a dreamy atmosphere.\r\n•	Premium amenities: cake stand, customized LED name board\r\n•	Space offers projection and HD screen\r\n•	Pre-installed OTT apps for entertainment\r\n•	Wall lighting for a memorable event\r\n•	Perfect for couples and small groups\r\n•	Unforgettable, exclusive celebration\r\n', NULL, 1, 1500, 2, 5, 1, 300, '2025-12-20', '2099-12-31', NULL),
